YML_TEXT = YML_TEXT.replace(
    "  # ループバック配信では無視されます（10つとも自動生成・配信します）。",
    "  # ループバック配信では無視されます（11つとも自動生成・配信します）。")
n10e = YML_TEXT.count("all ten variants")
